2: // MODULE: Deep Review Strategy Heading
3: // ───────────────────────────────────────────────────────────────────
4: 
5: import { createRequire } from 'node:module';
6: import { describe, expect, it } from 'vitest';
7: 
8: // Regression coverage for the deep-review reducer's strategy-heading upsert. The
9: // strategy file is authored by an agent and may arrive in the canonical numbered
10: // dialect ("## 11. RULED OUT DIRECTIONS") or an un-numbered one ("## Ruled Out
11: // Directions"), or without the section at all. The reducer must resolve all three
12: // without halting the loop, while still failing closed on a genuinely corrupt file
13: // when the create-missing bootstrap is not requested.
14: 
15: const nodeRequire = createRequire(import.meta.url);
16: const { upsertHeadingSectionBefore, replaceAnchorSection } = nodeRequire('../../scripts/reduce-state.cjs') as {
17:   upsertHeadingSectionBefore: (
18:     content: string,
19:     heading: string,
20:     body: string,
21:     beforeHeading: string,
22:     options?: { createMissing?: boolean },
23:   ) => string;
24:   replaceAnchorSection: (
25:     content: string,
26:     anchorId: string,
27:     heading: string,
28:     body: string,
29:     options?: { createMissing?: boolean },
30:   ) => string;
31: };
32: 
33: const HEADING = '10A. SATURATED / SWEPT DIMENSIONS AND EXPANSION FRONTIER';
34: const BEFORE = '11. RULED OUT DIRECTIONS';
35: const BODY = '- Completed pivots: 0';
36: 
37: describe('upsertHeadingSectionBefore — strategy-heading dialect tolerance', () => {
38:   it('inserts before a canonical numbered heading, preserving it (normal path unchanged)', () => {
39:     const content = '# Deep Review Strategy\n\n## 11. RULED OUT DIRECTIONS\n[none]\n';
40:     const out = upsertHeadingSectionBefore(content, HEADING, BODY, BEFORE);
41:     expect(out).toContain('## 10A. SATURATED');
42:     expect(out).toContain('## 11. RULED OUT DIRECTIONS');
43:     expect(out.indexOf('## 10A. SATURATED')).toBeLessThan(out.indexOf('## 11. RULED OUT DIRECTIONS'));
44:   });
45: 
46:   it('inserts before an un-numbered heading dialect, preserving the authored text verbatim', () => {
47:     const content = '# Deep Review Strategy\n\n## Ruled Out Directions\n[none]\n';
48:     const out = upsertHeadingSectionBefore(content, HEADING, BODY, BEFORE);
49:     expect(out).toContain('## 10A. SATURATED');
50:     // The authored heading is kept as-is, not silently renumbered.
51:     expect(out).toContain('## Ruled Out Directions');
52:   });
53: 
54:   it('bootstraps (appends) when the insertion heading is absent and createMissing is set', () => {
55:     const content = '# Deep Review Strategy\n\n## Topic\nx\n';
56:     const out = upsertHeadingSectionBefore(content, HEADING, BODY, BEFORE, { createMissing: true });
57:     expect(out).toContain('## 10A. SATURATED');
58:     expect(out.startsWith('# Deep Review Strategy')).toBe(true);
59:   });
60: 
61:   it('fails closed (throws) when the insertion heading is absent without createMissing', () => {
62:     const content = '# Deep Review Strategy\n\n## Topic\nx\n';
63:     expect(() => upsertHeadingSectionBefore(content, HEADING, BODY, BEFORE)).toThrow(/Missing insertion heading/);
64:   });
65: 
66:   it('updates an existing section in place — idempotent, no duplicate', () => {
67:     const base = '# Deep Review Strategy\n\n## 11. RULED OUT DIRECTIONS\n[none]\n';
68:     const seeded = upsertHeadingSectionBefore(base, HEADING, 'old body', BEFORE);
69:     const updated = upsertHeadingSectionBefore(seeded, HEADING, 'new body', BEFORE);
70:     expect(updated.match(/## 10A\. SATURATED/g)?.length).toBe(1);
71:     expect(updated).toContain('new body');
72:     expect(updated).not.toContain('old body');
73:   });
74: });
75: 
76: // Regression coverage for replaceAnchorSection's dialect fallback. The
77: // deep-review-strategy.md template wraps each machine-owned section in
78: // `<!-- MACHINE-OWNED: START/END -->` comments keyed by heading text, while
79: // the reducer's primary contract keys sections by `<!-- ANCHOR:id -->`
80: // comments. Without a fallback, a freshly-templated file has zero ANCHOR
81: // comments, so the reducer either throws (createMissing:false) or appends a
82: // second copy of the section (createMissing:true) instead of updating the
83: // MACHINE-OWNED-wrapped section already in the file.
84: describe('replaceAnchorSection — MACHINE-OWNED template dialect fallback', () => {
85:   const ANCHOR_ID = 'review-dimensions';
86:   const HEADING_TEXT = '3. REVIEW DIMENSIONS (remaining)';
87:   const BODY = '- [ ] D1 Correctness';
88: 
89:   it('updates a MACHINE-OWNED-wrapped section in place instead of appending a duplicate', () => {
90:     const template = [
91:       '# Deep Review Strategy',
92:       '',
93:       '## 3. REVIEW DIMENSIONS (remaining)',
94:       '<!-- MACHINE-OWNED: START -->',
95:       '- [ ] D1 Correctness, Logic errors',
96:       '- [ ] D2 Security',
97:       '<!-- MACHINE-OWNED: END -->',
98:       '',
99:       '---',
100:       '',
101:       '## 4. NON-GOALS',
102:       '[none]',
103:       '',
104:     ].join('\n');
105: 
106:     // No createMissing flag: this must resolve via the heading fallback, not
107:     // the create-missing bootstrap path, proving the fallback alone (not a
108:     // bootstrap flag) is what stops the duplication.
109:     const out = replaceAnchorSection(template, ANCHOR_ID, HEADING_TEXT, BODY);
110: 
111:     expect(out.match(/## 3\. REVIEW DIMENSIONS \(remaining\)/g)?.length).toBe(1);
112:     expect(out).toContain(BODY);
113:     // The originally-templated content for this section is gone -- it was
114:     // replaced in place, not left behind alongside an appended duplicate.
115:     expect(out).not.toContain('D2 Security');
116:     // The unrelated section below is untouched.
117:     expect(out).toContain('## 4. NON-GOALS');
118:   });
119: 
120:   it('is idempotent once normalized to the ANCHOR dialect', () => {
121:     const template = [
122:       '## 3. REVIEW DIMENSIONS (remaining)',
123:       '<!-- MACHINE-OWNED: START -->',
124:       '- [ ] D1 Correctness',
125:       '<!-- MACHINE-OWNED: END -->',
126:       '',
127:     ].join('\n');
128:     const once = replaceAnchorSection(template, ANCHOR_ID, HEADING_TEXT, BODY, { createMissing: true });
129:     const twice = replaceAnchorSection(once, ANCHOR_ID, HEADING_TEXT, BODY, { createMissing: true });
130:     expect(twice.match(/## 3\. REVIEW DIMENSIONS \(remaining\)/g)?.length).toBe(1);
131:     expect(twice).toBe(once);
132:   });
133: 
134:   it('still bootstraps by appending when the heading is genuinely absent and createMissing is set', () => {
135:     const content = '# Deep Review Strategy\n\n## Topic\nx\n';
136:     const out = replaceAnchorSection(content, ANCHOR_ID, HEADING_TEXT, BODY, { createMissing: true });
137:     expect(out).toContain(`<!-- ANCHOR:${ANCHOR_ID} -->`);
138:     expect(out).toContain(BODY);
139:   });
140: 
141:   it('fails closed with a MISSING_ANCHOR code when the heading is absent and createMissing is not set', () => {
142:     const content = '# Deep Review Strategy\n\n## Topic\nx\n';
143:     let caught: (Error & { code?: string }) | null = null;
144:     try {
145:       replaceAnchorSection(content, ANCHOR_ID, HEADING_TEXT, BODY);
146:     } catch (error) {
147:       caught = error as Error & { code?: string };
148:     }
149:     expect(caught).not.toBeNull();
150:     expect(caught?.message).toMatch(/Missing machine-owned anchor/);
151:     expect(caught?.code).toBe('MISSING_ANCHOR');
152:   });
153: });
154: 
155: // String.replace reads `$\``, `$&` and `$'` in a string replacement as
156: // match-relative text, so a section body quoting one of them must still be
157: // written verbatim instead of splicing a copy of the surrounding file.
158: describe('strategy section writers keep replacement patterns literal', () => {
159:   const LITERAL_BODY = "- [ ] Does `PluginInput.$` survive, and do $& and $' stay literal?";
160: 
161:   it('replaceAnchorSection writes the body verbatim over an ANCHOR section', () => {
162:     const content = [
163:       '# Deep Review Strategy',
164:       '',
165:       '<!-- ANCHOR:review-dimensions -->',
166:       '## 3. REVIEW DIMENSIONS (remaining)',
167:       '- [ ] D1 Correctness',
168:       '<!-- /ANCHOR:review-dimensions -->',
169:       '',
170:     ].join('\n');
171:     const out = replaceAnchorSection(content, 'review-dimensions', '3. REVIEW DIMENSIONS (remaining)', LITERAL_BODY);
172:     expect(out).toContain(LITERAL_BODY);
173:     expect(out.match(/# Deep Review Strategy/g)?.length).toBe(1);
174:   });
175: 
176:   it('replaceAnchorSection writes the body verbatim through the heading fallback', () => {
177:     const content = [
178:       '# Deep Review Strategy',
179:       '',
180:       '## 3. REVIEW DIMENSIONS (remaining)',
181:       '<!-- MACHINE-OWNED: START -->',
182:       '- [ ] D1 Correctness',
183:       '<!-- MACHINE-OWNED: END -->',
184:       '',
185:     ].join('\n');
186:     const out = replaceAnchorSection(content, 'review-dimensions', '3. REVIEW DIMENSIONS (remaining)', LITERAL_BODY);
187:     expect(out).toContain(LITERAL_BODY);
188:     expect(out.match(/# Deep Review Strategy/g)?.length).toBe(1);
189:   });
190: 
191:   it('upsertHeadingSectionBefore writes the body verbatim over an existing heading', () => {
192:     const content = `# Deep Review Strategy\n\n## ${HEADING}\n- old\n\n## ${BEFORE}\n[none]\n`;
193:     const out = upsertHeadingSectionBefore(content, HEADING, LITERAL_BODY, BEFORE);
194:     expect(out).toContain(LITERAL_BODY);
195:     expect(out.match(/# Deep Review Strategy/g)?.length).toBe(1);
196:   });
197: });

