33: const WORKSPACE_ROOT = path.resolve(__dirname, '..', '..', '..', '..', '..');
34: const CONTRACT_RELATIVE_PATH = '.skilled/skills/system-deep-loop/deep-review/assets/review-mode-contract.yaml';
35: const SNAPSHOT_ARTIFACT_ID = 'review-contract-snapshot';
36: const MAPPING_KEY_PATTERN = /^([A-Za-z_][A-Za-z0-9_]*):(?: (.*))?$/;
37: const SNAPSHOT_FRONTMATTER = `---
38: title: "Deep Review Review-Mode Contract Snapshot"
39: description: "Human-readable snapshot of the deep-review contract: targets, dimensions, severities, gates, convergence, outputs, and validation."
40: trigger_phrases:
41:   - "deep-review contract snapshot"
42:   - "review-mode contract"
43:   - "review dimensions"
44:   - "convergence gates"
45: importance_tier: high
46: contextType: implementation
47: version: 1.11.0.0
