253: // ─────────────────────────────────────────────────────────────────────────────
254: // 5. MARKDOWN RENDER HELPERS
255: // ─────────────────────────────────────────────────────────────────────────────
256: 
257: function escapeCell(value) {
258:   if (value === null || value === undefined) return '';
259:   return String(value).replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
260: }
261: 
262: function renderTable(headers, rows) {
263:   const headerLine = `| ${headers.join(' | ')} |`;
264:   const dividerLine = `|${headers.map(() => ' --- ').join('|')}|`;
265:   const bodyLines = rows.map((row) => `| ${row.map(escapeCell).join(' | ')} |`);
266:   return [headerLine, dividerLine, ...bodyLines].join('\n');
267: }
268: 
269: function renderIdList(values) {
270:   return (values || []).map((value) => `\`${value}\``).join(', ');
271: }
