273: // ─────────────────────────────────────────────────────────────────────────────
274: // 6. SECTION RENDERERS
275: // ─────────────────────────────────────────────────────────────────────────────
276: 
277: function renderMetaSection(doc) {
278:   const meta = doc.meta || {};
279:   const rows = [
280:     ['ownerSkill', meta.ownerSkill],
281:     ['reviewModeVersion', meta.reviewModeVersion],
282:     ['sourceOfTruth', meta.sourceOfTruth ? `\`${meta.sourceOfTruth}\`` : ''],
283:   ];
284:   if (meta.generatedNotice && meta.generatedNotice.warning) {
285:     rows.push(['generatedNotice.warning', meta.generatedNotice.warning]);
286:   }
287:   return ['## Meta', '', renderTable(['Field', 'Value'], rows)].join('\n');
288: }
