290: function renderTargetTypesSection(doc) {
291:   const rows = (doc.contract.targetTypes || []).map((item) => [`\`${item.id}\``, item.label, item.description]);
292:   return ['## Target Types', '', renderTable(['ID', 'Label', 'Description'], rows)].join('\n');
293: }
