295: function renderDimensionsSection(doc) {
296:   const rows = (doc.contract.dimensions || []).map((item) => [
297:     `\`${item.id}\``,
298:     item.priority,
299:     item.label,
300:     item.checks,
301:     item.requiredForSeverityCoverage ? 'yes' : 'no',
302:   ]);
303:   return [
304:     '## Dimensions',
305:     '',
306:     renderTable(['ID', 'Priority', 'Label', 'Checks', 'Required For Severity Coverage'], rows),
307:   ].join('\n');
308: }
309: 
310: function renderSeveritiesSection(doc) {
311:   const rows = (doc.contract.severities || []).map((item) => [
312:     `\`${item.id}\``,
313:     item.weight,
314:     item.label,
315:     item.requiresFileLineEvidence ? 'yes' : 'no',
316:   ]);
317:   return ['## Severities', '', renderTable(['ID', 'Weight', 'Label', 'Requires File:Line Evidence'], rows)].join('\n');
318: }
