320: function renderVerdictsSection(doc) {
321:   const rows = (doc.contract.verdicts || []).map((item) => [
322:     `\`${item.id}\``,
323:     item.label,
324:     item.condition,
325:     item.nextCommand,
326:     item.hasAdvisoriesMetadata || '',
327:   ]);
328:   return [
329:     '## Verdicts',
330:     '',
331:     renderTable(['ID', 'Label', 'Condition', 'Next Command', 'Advisories Metadata'], rows),
332:   ].join('\n');
333: }
334: 
335: function renderQualityGatesSection(doc) {
336:   const rows = (doc.contract.qualityGates || []).map((item) => [
337:     `\`${item.id}\``,
338:     item.label,
339:     item.binary ? 'yes' : 'no',
340:     renderIdList(item.combines),
341:     item.rule,
342:   ]);
343:   return ['## Quality Gates', '', renderTable(['ID', 'Label', 'Binary', 'Combines', 'Rule'], rows)].join('\n');
344: }
345: 
346: function renderSettingsTable(settingsObject) {
347:   const rows = Object.entries(settingsObject || {}).map(([key, value]) => [key, Array.isArray(value) ? renderIdList(value) : value]);
348:   return renderTable(['Setting', 'Value'], rows);
349: }
