351: function renderConvergenceSection(doc) {
352:   const convergence = doc.contract.convergence || {};
353:   const signalRows = (convergence.signals || []).map((item) => [`\`${item.id}\``, item.weight, item.description]);
354:   return [
355:     '## Convergence',
356:     '',
357:     '### Defaults',
358:     '',
359:     renderSettingsTable(convergence.defaults),
360:     '',
361:     '### Signals',
362:     '',
363:     renderTable(['ID', 'Weight', 'Description'], signalRows),
364:     '',
365:     '### Severity Math',
366:     '',
367:     renderSettingsTable(convergence.severityMath),
368:     '',
369:     '### Coverage Age',
370:     '',
371:     renderSettingsTable(convergence.coverageAge),
372:     '',
373:     '### Thresholds',
374:     '',
375:     renderSettingsTable(convergence.thresholds),
376:   ].join('\n');
377: }
378: 
379: function renderCrossReferenceProtocolsSection(doc) {
380:   const protocols = doc.contract.crossReferenceProtocols || [];
381:   const summaryRows = protocols.map((item) => [
382:     `\`${item.id}\``,
383:     item.dimension,
384:     item.level,
385:     item.gateClass,
386:     renderIdList(item.appliesTo),
387:   ]);
388:   const detailLines = [];
389:   for (const protocol of protocols) {
390:     detailLines.push(`### \`${protocol.id}\``, '');
391:     detailLines.push(`- **Pass:** ${protocol.passCriteria}`);
392:     detailLines.push(`- **Partial:** ${protocol.partialCriteria}`);
393:     detailLines.push(`- **Fail:** ${protocol.failCriteria}`);
394:     detailLines.push('');
395:   }
396:   return [
397:     '## Cross-Reference Protocols',
398:     '',
399:     renderTable(['ID', 'Dimension', 'Level', 'Gate Class', 'Applies To'], summaryRows),
400:     '',
401:     ...detailLines,
402:   ].join('\n').trimEnd();
403: }
404: 
405: function renderOutputsSection(doc) {
406:   const outputs = doc.contract.outputs || {};
407:   const lines = ['## Outputs', ''];
408:   for (const [id, spec] of Object.entries(outputs)) {
409:     lines.push(`### \`${id}\``, '');
410:     if (spec.pathPattern) lines.push(`- **Path pattern:** \`${spec.pathPattern}\``);
411:     if (spec.machineOwned !== undefined) lines.push(`- **Machine owned:** ${spec.machineOwned ? 'yes' : 'no'}`);
412:     if (Array.isArray(spec.sections)) lines.push(`- **Sections:** ${renderIdList(spec.sections)}`);
413:     if (Array.isArray(spec.fields)) lines.push(`- **Fields:** ${renderIdList(spec.fields)}`);
414:     if (Array.isArray(spec.requiredSections)) lines.push(`- **Required sections:** ${renderIdList(spec.requiredSections)}`);
415:     if (spec.description) lines.push(`- **Description:** ${spec.description}`);
416:     if (spec.iterationRecord) {
417:       lines.push(`- **Iteration record required:** ${renderIdList(spec.iterationRecord.required)}`);
418:       lines.push(`- **Iteration record optional:** ${renderIdList(spec.iterationRecord.optional)}`);
419:     }
420:     if (spec.synthesisEvent) {
421:       lines.push(`- **Synthesis event required:** ${renderIdList(spec.synthesisEvent.required)}`);
422:     }
423:     lines.push('');
424:   }
425:   return lines.join('\n').trimEnd();
