428: function renderValidationSection(doc) {
429:   const validation = doc.validation || {};
430:   const rows = (validation.checks || []).map((item) => [`\`${item.id}\``, item.description]);
431:   return [
432:     '## Validation',
433:     '',
434:     `Schema version: ${validation.schemaVersion}`,
435:     '',
436:     renderTable(['ID', 'Description'], rows),
437:   ].join('\n');
438: }
439: 
440: const SECTION_RENDERERS = {
441:   meta: renderMetaSection,
442:   'target-types': renderTargetTypesSection,
443:   dimensions: renderDimensionsSection,
444:   severities: renderSeveritiesSection,
445:   verdicts: renderVerdictsSection,
446:   'quality-gates': renderQualityGatesSection,
447:   convergence: renderConvergenceSection,
448:   'cross-reference-protocols': renderCrossReferenceProtocolsSection,
449:   outputs: renderOutputsSection,
450:   validation: renderValidationSection,
451: };
