50: // ─────────────────────────────────────────────────────────────────────────────
51: // 3. YAML SUBSET PARSER
52: // ─────────────────────────────────────────────────────────────────────────────
53: 
54: function tokenizeLines(rawText) {
55:   const rawLines = rawText.split(/\r?\n/);
56:   const lines = [];
57:   for (let index = 0; index < rawLines.length; index += 1) {
58:     const rawLine = rawLines[index];
59:     if (rawLine.trim() === '') continue;
60:     const stripped = rawLine.replace(/^ */, '');
61:     if (stripped.startsWith('#')) continue;
62:     const indent = rawLine.length - stripped.length;
63:     lines.push({ indent, text: stripped.replace(/\s+$/, ''), lineNumber: index + 1 });
64:   }
65:   return lines;
66: }
67: 
68: function isDashLine(text) {
69:   return text === '-' || text.startsWith('- ');
70: }
71: 
72: function parseScalarText(rawText) {
73:   const text = rawText.trim();
74:   if (text === '') return null;
75:   if (text.startsWith('[') && text.endsWith(']')) {
76:     const inner = text.slice(1, -1).trim();
77:     if (inner === '') return [];
78:     return inner.split(',').map((part) => parseScalarText(part.trim()));
79:   }
80:   if (text.length >= 2 && text.startsWith('"') && text.endsWith('"')) {
81:     return text.slice(1, -1).replace(/\\"/g, '"');
82:   }
83:   if (text.length >= 2 && text.startsWith("'") && text.endsWith("'")) {
84:     return text.slice(1, -1).replace(/''/g, "'");
85:   }
86:   if (text === 'true') return true;
87:   if (text === 'false') return false;
88:   if (text === 'null' || text === '~') return null;
89:   if (/^-?\d+(\.\d+)?$/.test(text)) return Number(text);
90:   return text;
91: }
92: 
93: function parseBlock(lines, index, indent) {
94:   if (index >= lines.length || lines[index].indent < indent) {
95:     return { value: null, next: index };
96:   }
97:   if (isDashLine(lines[index].text)) {
98:     return parseSequence(lines, index, indent);
99:   }
100:   return parseMapping(lines, index, indent);
101: }
102: 
103: function parseSequence(lines, index, indent) {
104:   const array = [];
105:   let cursor = index;
106:   while (cursor < lines.length && lines[cursor].indent === indent && isDashLine(lines[cursor].text)) {
107:     const line = lines[cursor];
108:     const rest = line.text === '-' ? '' : line.text.slice(2);
109:     if (rest.trim() === '') {
110:       cursor += 1;
111:       if (cursor < lines.length && lines[cursor].indent > indent) {
112:         const child = parseBlock(lines, cursor, lines[cursor].indent);
113:         array.push(child.value);
114:         cursor = child.next;
115:       } else {
116:         array.push(null);
117:       }
118:       continue;
119:     }
120:     const keyMatch = rest.match(MAPPING_KEY_PATTERN);
121:     if (keyMatch) {
122:       const itemIndent = indent + 2;
123:       const obj = {};
124:       const firstKey = keyMatch[1];
125:       const firstValueRaw = keyMatch[2];
126:       cursor += 1;
127:       if (firstValueRaw !== undefined && firstValueRaw.trim() !== '') {
128:         obj[firstKey] = parseScalarText(firstValueRaw);
129:       } else if (cursor < lines.length && lines[cursor].indent > itemIndent) {
130:         const child = parseBlock(lines, cursor, lines[cursor].indent);
131:         obj[firstKey] = child.value;
132:         cursor = child.next;
133:       } else {
134:         obj[firstKey] = null;
135:       }
136:       while (cursor < lines.length && lines[cursor].indent === itemIndent && !isDashLine(lines[cursor].text)) {
137:         const entry = parseMappingEntry(lines, cursor, itemIndent);
138:         obj[entry.key] = entry.value;
139:         cursor = entry.next;
140:       }
141:       array.push(obj);
142:       continue;
143:     }
144:     array.push(parseScalarText(rest));
145:     cursor += 1;
146:   }
147:   return { value: array, next: cursor };
148: }
149: 
150: function parseMapping(lines, index, indent) {
151:   const obj = {};
152:   let cursor = index;
153:   while (cursor < lines.length && lines[cursor].indent === indent && !isDashLine(lines[cursor].text)) {
154:     const entry = parseMappingEntry(lines, cursor, indent);
155:     obj[entry.key] = entry.value;
156:     cursor = entry.next;
157:   }
158:   return { value: obj, next: cursor };
159: }
160: 
161: function parseMappingEntry(lines, index, indent) {
162:   const line = lines[index];
163:   const match = line.text.match(MAPPING_KEY_PATTERN);
164:   if (!match) {
165:     throw new Error(`Cannot parse YAML mapping entry at line ${line.lineNumber}: "${line.text}"`);
166:   }
167:   const key = match[1];
168:   const rawValue = match[2];
169:   let value;
170:   let next = index + 1;
171:   if (rawValue !== undefined && rawValue.trim() !== '') {
172:     value = parseScalarText(rawValue);
173:   } else if (next < lines.length && lines[next].indent > indent) {
174:     const child = parseBlock(lines, next, lines[next].indent);
175:     value = child.value;
176:     next = child.next;
177:   } else {
178:     value = null;
179:   }
180:   return { key, value, next };
181: }
182: 
183: function parseYamlDocument(rawText) {
184:   const lines = tokenizeLines(rawText);
185:   if (lines.length === 0) return {};
186:   return parseBlock(lines, 0, lines[0].indent).value;
187: }
