193: function assertContractShape(doc) {
194:   const problems = [];
195:   if (!doc || typeof doc !== 'object') problems.push('document root is not a mapping');
196:   if (!doc.meta) problems.push('missing top-level "meta"');
197:   if (!doc.contract) problems.push('missing top-level "contract"');
198:   if (!doc.render) problems.push('missing top-level "render"');
199:   if (!doc.validation) problems.push('missing top-level "validation"');
200: 
201:   const requiredContractKeys = [
202:     'targetTypes',
203:     'dimensions',
204:     'severities',
205:     'verdicts',
206:     'qualityGates',
207:     'convergence',
208:     'crossReferenceProtocols',
209:     'outputs',
210:   ];
211:   for (const key of requiredContractKeys) {
212:     if (!doc.contract || doc.contract[key] === undefined) {
213:       problems.push(`missing "contract.${key}"`);
214:     }
215:   }
216:   if (!doc.validation || !Array.isArray(doc.validation.checks)) {
217:     problems.push('missing "validation.checks" list');
218:   }
219:   if (!doc.render || !Array.isArray(doc.render.artifacts)) {
220:     problems.push('missing "render.artifacts" list');
221:   }
222: 
223:   if (problems.length > 0) {
224:     throw new Error(`review_mode_contract.yaml does not match the shape this renderer expects:\n- ${problems.join('\n- ')}`);
225:   }
226: }
