228: function resolveSnapshotArtifact(doc) {
229:   const artifacts = doc.render.artifacts;
230:   const snapshotArtifact = artifacts.find((artifact) => artifact && artifact.id === SNAPSHOT_ARTIFACT_ID);
231:   if (!snapshotArtifact) {
232:     throw new Error(`review_mode_contract.yaml render.artifacts is missing the "${SNAPSHOT_ARTIFACT_ID}" entry`);
233:   }
234:   if (artifacts.length !== 1) {
235:     throw new Error(
236:       `review_mode_contract.yaml render.artifacts declares ${artifacts.length} artifacts, but this script only ` +
237:       `supports the single "${SNAPSHOT_ARTIFACT_ID}" target. Either remove the extra artifact or extend this ` +
238:       'script (and its manifest markers) before adding more render targets.',
239:     );
240:   }
241:   if (!snapshotArtifact.markers || !snapshotArtifact.markers.begin || !snapshotArtifact.markers.end) {
242:     throw new Error(`review_mode_contract.yaml render.artifacts[0] ("${SNAPSHOT_ARTIFACT_ID}") is missing markers.begin/markers.end`);
243:   }
244:   if (!Array.isArray(snapshotArtifact.sections) || snapshotArtifact.sections.length === 0) {
245:     throw new Error(`review_mode_contract.yaml render.artifacts[0] ("${SNAPSHOT_ARTIFACT_ID}") is missing a non-empty sections list`);
246:   }
247:   if (!snapshotArtifact.path) {
