262: function renderTable(headers, rows) {
263:   const headerLine = `| ${headers.join(' | ')} |`;
264:   const dividerLine = `|${headers.map(() => ' --- ').join('|')}|`;
265:   const bodyLines = rows.map((row) => `| ${row.map(escapeCell).join(' | ')} |`);
266:   return [headerLine, dividerLine, ...bodyLines].join('\n');
