490: // ─────────────────────────────────────────────────────────────────────────────
491: // 8. CLI ENTRY POINT
492: // ─────────────────────────────────────────────────────────────────────────────
493: 
494: function relPath(absolutePath) {
495:   return path.relative(WORKSPACE_ROOT, absolutePath).split(path.sep).join('/');
496: }
497: 
498: function loadContractDocument() {
499:   const contractPath = path.join(WORKSPACE_ROOT, CONTRACT_RELATIVE_PATH);
500:   const contractText = fs.readFileSync(contractPath, 'utf8');
501:   const doc = parseYamlDocument(contractText);
502:   assertContractShape(doc);
503:   return doc;
504: }
505: 
506: function run(argv = process.argv.slice(2)) {
507:   // Only --check is known; any other token must fail here, before the
508:   // no-check fallthrough can choose the write path and rewrite the snapshot.
509:   const unknown = argv.find((arg) => arg !== '--check');
510:   if (unknown !== undefined) {
511:     process.stderr.write(`render-contract-snapshot.cjs: unknown option: ${unknown}\n`);
512:     process.stderr.write('usage: render-contract-snapshot.cjs [--check]\n');
513:     return 2;
514:   }
515:   const checkOnly = argv.includes('--check');
516:   const doc = loadContractDocument();
517:   const snapshotArtifact = resolveSnapshotArtifact(doc);
518:   const rendered = renderSnapshot(doc, snapshotArtifact);
519:   const outputPath = path.resolve(WORKSPACE_ROOT, snapshotArtifact.path);
520: 
521:   if (checkOnly) {
522:     const existing = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, 'utf8') : null;
523:     if (existing !== rendered) {
524:       process.stderr.write(`[render-contract-snapshot] drift detected: ${relPath(outputPath)} is stale. Run without --check to regenerate.\n`);
525:       return 1;
526:     }
527:     process.stdout.write(`[render-contract-snapshot] OK: ${relPath(outputPath)} is up to date.\n`);
528:     return 0;
529:   }
530: 
531:   fs.mkdirSync(path.dirname(outputPath), { recursive: true });
532:   fs.writeFileSync(outputPath, rendered, 'utf8');
533:   process.stdout.write(`[render-contract-snapshot] wrote ${relPath(outputPath)}\n`);
534:   return 0;
535: }
536: 
537: if (require.main === module) {
538:   try {
539:     process.exitCode = run();
540:   } catch (error) {
541:     process.stderr.write(`[render-contract-snapshot] ${error instanceof Error ? error.message : String(error)}\n`);
542:     process.exitCode = 1;
543:   }
544: }
545: 
546: // ─────────────────────────────────────────────────────────────────────────────
547: // 9. EXPORTS
548: // ─────────────────────────────────────────────────────────────────────────────
549: 
550: module.exports = {
551:   WORKSPACE_ROOT,
552:   CONTRACT_RELATIVE_PATH,
553:   parseYamlDocument,
554:   assertContractShape,
555:   resolveSnapshotArtifact,
556:   renderSnapshot,
557:   loadContractDocument,
558:   run,
559: };

